constexpr int complex_init(int base) {
    return (base * 128) + 42;
}

struct Configuration {
    static constexpr int MAGIC_BASE = 5;

    // Member initialized directly via constant expression
    const int fixed_checksum = complex_init(MAGIC_BASE);

    // Member initialized using the result of the fixed value
    const int calculated_offset;

    // Ensure all members are initialized in the constructor
    Configuration()
      : calculated_offset(fixed_checksum / 2) {}
};
